package com.mendes.scheduling_platform.venue; import com.mendes.scheduling_platform.exception.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class VenueService { private final VenueRepository repo; public VenueService(VenueRepository r){repo=r;} public List<Venue> list(Long t){return repo.findAllByTenantId(t);} public Venue get(Long t,Long id){return repo.findByIdAndTenantId(id,t).orElseThrow(()->new NotFoundException("Espaço não encontrado"));} public Venue save(Long t,Venue v){if(v.getPrice()==null||v.getPrice().signum()<0||v.getDurationMinutes()==null||v.getDurationMinutes()<1)throw new BusinessException("Preço e duração inválidos");v.setId(null);v.setTenantId(t);return repo.save(v);} public Venue update(Long t,Long id,Venue in){Venue v=get(t,id);v.setName(in.getName());v.setDescription(in.getDescription());v.setType(in.getType());v.setPrice(in.getPrice());v.setDurationMinutes(in.getDurationMinutes());v.setActive(in.isActive());return repo.save(v);} public void delete(Long t,Long id){repo.delete(get(t,id));} }
